"use client";

import { ArrowLeft, ArrowRight, RotateCcw } from "lucide-react";
import * as React from "react";

import { Button } from "@/components/ui/button";

/**
 * The multi-step form machinery, extracted so it exists once.
 *
 * Two React hazards cost real debugging time on the agency form, and both produced the same
 * symptom: everything the person had typed silently disappeared while the screen looked
 * completely normal. Neither is obvious from reading the component that has them. So the
 * machinery lives here, with the fixes baked in, and a second form cannot reintroduce them.
 *
 * **Hazard one: a component defined inside a component.** `Field` below is at module scope
 * and must stay there. Declared inside the form, it is a new function identity on every
 * render, so React sees a different component type, unmounts the subtree and mounts a fresh
 * one. Every uncontrolled input inside it goes blank. It looks exactly like a broken
 * persistence layer.
 *
 * **Hazard two: two buttons reconciled as one.** `StepNav` gives the Continue button and the
 * submit button distinct keys. Without them React reuses a single DOM node and only changes
 * `type` from "button" to "submit". Setting state in the click handler flips that attribute
 * while the browser is still processing the click, so it performs the default action and
 * submits the form. On the agency form that submitted an incomplete body, the action failed
 * validation, React reset the form, and the first two steps were wiped on the way to the
 * third.
 *
 * Everything else here is the accessibility and anti-spam behaviour the brief requires:
 * announced progress, focus moving to the new step's heading, steps hidden rather than
 * unmounted so nothing is lost and nothing hidden is reachable by keyboard, a draft that
 * survives a browser close, and a timing stamp taken on submit rather than at render.
 */

/*
 * The three shared form primitives, drawn as ruled lines rather than as boxes.
 *
 * Every form on both front doors reads from these, so this is where the design system
 * either reaches the forms or does not. It did not: the sell page and the agency
 * qualification form were still rendering boxed inputs with pill radii while the rest of
 * the site had been redrawn, which is exactly the "one component that has not been redrawn
 * looks pasted in" failure the direction warns about.
 *
 * An input is a LINE. It carries a 2px bottom rule in --rn-line-interactive, which is the
 * token that clears the 3:1 that SC 1.4.11 requires of a boundary that IS the control, and
 * it is set at body size rather than small text because a person is typing into it.
 *
 * A choice is a ROW, and its selected state is the ink flip the rest of the product uses,
 * not a tinted background. The `has-[:checked]` selector keeps that working without any
 * JavaScript, which matters because these forms work before hydration.
 */
export const LABEL_CLASS =
  "block font-display text-label font-bold uppercase tracking-[var(--tracking-widest)] text-ink-muted [font-variation-settings:'wdth'_100]";
export const INPUT_CLASS =
  "mt-2 min-h-11 w-full border-0 border-b-2 border-line-interactive bg-transparent px-0 text-base font-medium text-ink placeholder:text-ink-muted";
/*
 * A choice is a ROW, and until now this class did not draw one.
 *
 * The comment above has said "a choice is a ROW, and its selected state is the ink flip" since
 * the primitives were written, and the class underneath it drew a box on all four sides. So step
 * two of the sell form was eleven thin-bordered rectangles in a two-column grid, and because two
 * of the four groups have three options, two of those rectangles sat alone on a row with a full
 * empty cell beside them. Eleven grey-bordered boxes with two holes in the grid is the exact
 * object the redesign exists to remove, on the one screen that is nothing but choices.
 *
 * Now it is a row: no border, a hairline between rows only, full width, and the ink flip it
 * always claimed. The rule is on the TOP of each row so the group closes on the rule below the
 * last one, which is how every other list on the site is ruled.
 */
export const CHOICE_CLASS =
  "flex min-h-12 w-full cursor-pointer items-center gap-4 border-t border-line px-2 text-sm transition-colors duration-[var(--duration-micro)] hover:bg-ink hover:text-ink-inverse has-[:checked]:bg-ink has-[:checked]:font-semibold has-[:checked]:text-ink-inverse";

/** A labelled field. Module scope, deliberately. See hazard one above. */
export function Field({
  name,
  label,
  hint,
  error,
  children,
}: {
  name: string;
  label: string;
  hint?: string;
  error?: string;
  children: React.ReactNode;
}) {
  return (
    /*
     * A column that pushes its control to the bottom, so two fields side by side rule together.
     *
     * The hint sat between the label and the input, so a field with a hint pushed its own rule
     * down and a field without one did not. Year and Mileage share a row on the sell form, and
     * their 2px rules sat 21px apart: two underlines at two different heights, in a design whose
     * entire idea is that a rule is where a control is. Every pair on both forms did it.
     *
     * `h-full` plus `mt-auto` on the control fixes it without moving the hint, which belongs
     * above the field a person is about to type in rather than below it.
     */
    <div className="flex h-full flex-col">
      <label htmlFor={name} className={LABEL_CLASS}>
        {label}
      </label>
      {hint ? (
        <p id={`${name}-hint`} className="mt-0.5 text-xs text-ink-muted">
          {hint}
        </p>
      ) : null}
      <div className="mt-auto">{children}</div>
      {error ? (
        <p id={`${name}-error`} className="mt-1 text-xs font-medium text-danger">
          {error}
        </p>
      ) : null}
    </div>
  );
}

/** A group of radios or checkboxes with its own legend, error and 44px targets. */
export function ChoiceGroup({
  name,
  legend,
  hint,
  type,
  options,
  error,
  columns = 2,
}: {
  name: string;
  legend: string;
  hint?: string;
  type: "radio" | "checkbox";
  options: readonly { value: string; label: string }[];
  error?: string;
  columns?: 1 | 2;
}) {
  return (
    <fieldset>
      <legend className={LABEL_CLASS}>{legend}</legend>
      {hint ? <p className="mt-0.5 text-xs text-ink-muted">{hint}</p> : null}
      {/*
        One column, with the rows ruled, and a closing rule under the last.
        ------------------------------------------------------------------
        Two columns left a hole whenever a group had an odd number of options, which two of the
        four on the sell form do. A ruled single column has no such arithmetic, reads top to
        bottom the way a list of options is read, and gives every row the full width to flip to
        ink, which is the feedback. The `columns` prop stays for callers that want a wide pair of
        short options, and it now splits the SAME ruled rows rather than switching to boxes.
      */}
      <div className={`mt-3 grid border-b border-line ${columns === 2 ? "sm:grid-cols-2" : ""}`}>
        {options.map((option) => (
          <label key={option.value} className={CHOICE_CLASS}>
            <input
              type={type}
              name={name}
              value={option.value}
              /*
               * The description goes on every control in the group, not on the fieldset.
               * A description on a fieldset is not reliably read when a radio inside it
               * takes focus, and focus landing on the control is how the person is told
               * what went wrong.
               */
              aria-invalid={error ? true : undefined}
              aria-describedby={error ? `${name}-error` : undefined}
              /*
               * `accent-color` on the ink rather than on red. A ticked option already flips its
               * whole row to ink, so a red dot inside a black row is a second mark saying the
               * same thing, in the one colour this palette rations.
               */
              className="size-4 shrink-0 accent-[var(--rn-ink)]"
            />
            {option.label}
          </label>
        ))}
      </div>
      {error ? (
        <p id={`${name}-error`} className="mt-1 text-xs font-medium text-danger">
          {error}
        </p>
      ) : null}
    </fieldset>
  );
}

/**
 * Put focus on the first control that failed, and report whether it found one.
 *
 * Validation was silent. Pressing Continue on an unanswered step redrew the same screen
 * with red text somewhere on it, focus still sitting on the Continue button, and nothing
 * announced. A screen reader user got no indication at all that anything had happened,
 * which is SC 4.1.3, and a sighted keyboard user had to hunt for the message.
 *
 * Focus is the fix rather than a live region, and deliberately so. Every control on these
 * forms already carries `aria-invalid` and an `aria-describedby` pointing at its own error
 * text, so landing on the control reads the label, the state and the reason in one go, and
 * leaves the caret in the field that needs typing. Announcing the same string a second time
 * through `role="alert"` would only make the reader say it twice.
 *
 * DOM order, not the order the validator happened to return, so the person is sent to the
 * first problem down the page. Inactive steps stay mounted with the `hidden` attribute so
 * that nothing typed is lost, which means their controls are still queryable and must be
 * skipped.
 */
export function focusFirstInvalid(
  form: HTMLFormElement | null,
  errors: Record<string, string>,
): boolean {
  if (!form) return false;

  const names = new Set(Object.keys(errors));
  if (names.size === 0) return false;

  for (const control of form.querySelectorAll<HTMLElement>("input, select, textarea")) {
    const { name } = control as HTMLInputElement;
    if (!name || !names.has(name)) continue;
    if (control.closest("[hidden]")) continue;

    control.focus();
    return true;
  }

  return false;
}

/**
 * Progress. A live region rather than a decorative bar, so the change is announced. The bar
 * itself is aria-hidden because the sentence already says it.
 */
export function StepProgress({
  step,
  steps,
}: {
  step: number;
  steps: readonly { title: string; hint: string }[];
}) {
  const current = steps[step] ?? steps[0];
  if (!current) return null;

  return (
    <div className="mb-6">
      <p role="status" aria-live="polite" className="text-sm font-semibold">
        Step {step + 1} of {steps.length}: {current.title}
        <span className="ml-2 font-normal text-ink-muted">{current.hint}</span>
      </p>
      {/*
        A rule in three parts, not three capsules.
        -----------------------------------------
        The unreached segments were `bg-surface-sunken`, which in dark theme is the ground the
        form is already standing on, so two of the three were invisible: on step one the
        indicator was a single red capsule floating on its own with nothing to be one third of.
        It also put a second red object in a viewport that already has the Continue button,
        which is the one rule this palette has, and it drew four rounded capsules on a system
        whose radius tokens are all zero.

        Ink for done, the strong hairline for not yet, 2px, square. The same rule the rest of
        the site uses to separate things, cut into as many parts as there are steps.
      */}
      <ol aria-hidden="true" className="mt-4 flex gap-1">
        {steps.map((item, index) => (
          <li
            key={item.title}
            className={`h-[2px] flex-1 ${index <= step ? "bg-ink" : "bg-line-strong"}`}
          />
        ))}
      </ol>
    </div>
  );
}

/** Back, Continue and submit. The keys are the fix for hazard two and must not be removed. */
export function StepNav({
  step,
  stepCount,
  pending,
  submitLabel,
  pendingLabel = "Sending",
  onBack,
  onNext,
  note,
}: {
  step: number;
  stepCount: number;
  pending: boolean;
  submitLabel: string;
  pendingLabel?: string;
  onBack: () => void;
  onNext: () => void;
  note?: string;
}) {
  const last = step >= stepCount - 1;

  return (
    <div className="mt-8 flex flex-wrap items-center gap-3 border-t border-line pt-6">
      {step > 0 ? (
        <Button key="nav-back" type="button" variant="secondary" onClick={onBack}>
          <ArrowLeft aria-hidden="true" />
          Back
        </Button>
      ) : null}

      {last ? (
        <Button key="nav-submit" type="submit" disabled={pending}>
          {pending ? pendingLabel : submitLabel}
          {pending ? null : <ArrowRight aria-hidden="true" />}
        </Button>
      ) : (
        <Button key="nav-continue" type="button" onClick={onNext}>
          Continue
          <ArrowRight aria-hidden="true" />
        </Button>
      )}

      {note ? <p className="text-xs text-ink-muted">{note}</p> : null}
    </div>
  );
}

/**
 * The honeypot and the timing stamp.
 *
 * Off screen rather than `sr-only`: an sr-only element is one pixel and still technically in
 * the viewport, so some password managers fill it and turn a real person into a discarded
 * submission.
 */
export function BotTraps({ elapsedRef }: { elapsedRef: React.RefObject<HTMLInputElement | null> }) {
  return (
    <>
      <div aria-hidden="true" className="absolute -left-[9999px] top-0 h-px w-px overflow-hidden">
        <label htmlFor="hp">Leave this empty</label>
        <input id="hp" name="hp" type="text" tabIndex={-1} autoComplete="off" />
      </div>
      <input ref={elapsedRef} type="hidden" name="elapsedMs" defaultValue="0" />
    </>
  );
}

type Draft = Record<string, string | string[]>;

type ActionState = { status: string; fieldErrors?: Record<string, string> };

export type MultiStepOptions = {
  /** localStorage key. Version it, so a changed field set does not restore into nothing. */
  storageKey: string;
  steps: readonly { title: string; hint: string }[];
  /** Which step each field belongs to, so a server error returns to the right screen. */
  fieldStep: Record<string, number>;
  /** The server action state, watched for field errors. */
  state: ActionState;
  /** Names that appear more than once, such as a checkbox group. */
  arrayFields?: readonly string[];
};

/**
 * Owns step state, draft persistence, focus management and the timing stamp.
 *
 * Validation stays with the caller, because the schema is form-specific: pass a validator to
 * `next()` that returns the errors for the step it was given.
 */
export function useMultiStepForm({
  storageKey,
  steps,
  fieldStep,
  state,
  arrayFields = [],
}: MultiStepOptions) {
  const [step, setStep] = React.useState(0);
  const [clientErrors, setClientErrors] = React.useState<Record<string, string>>({});
  const [restored, setRestored] = React.useState(false);

  const formRef = React.useRef<HTMLFormElement>(null);
  const headingRef = React.useRef<HTMLHeadingElement>(null);
  const elapsedField = React.useRef<HTMLInputElement>(null);
  const renderedAt = React.useRef<number>(Date.now());
  const shouldFocus = React.useRef(false);
  // Set when a render is about to paint validation errors, read once by the focus effect.
  const invalid = React.useRef<Record<string, string> | null>(null);

  const arrays = React.useMemo(() => new Set(arrayFields), [arrayFields]);

  // ---------------------------------------------------------------- draft persistence

  // biome-ignore lint/correctness/useExhaustiveDependencies: restores once, on mount, from the key this form was created with.
  React.useEffect(() => {
    const form = formRef.current;
    if (!form) return;

    try {
      const saved = window.localStorage.getItem(storageKey);
      if (!saved) return;

      const draft = JSON.parse(saved) as Draft;
      let any = false;

      for (const [name, value] of Object.entries(draft)) {
        const fields = form.elements.namedItem(name);
        if (!fields) continue;

        if (Array.isArray(value)) {
          for (const input of form.querySelectorAll<HTMLInputElement>(`[name="${name}"]`)) {
            input.checked = value.includes(input.value);
          }
          any = any || value.length > 0;
          continue;
        }

        if (fields instanceof RadioNodeList) {
          for (const input of form.querySelectorAll<HTMLInputElement>(`[name="${name}"]`)) {
            input.checked = input.value === value;
          }
        } else if (
          fields instanceof HTMLInputElement ||
          fields instanceof HTMLTextAreaElement ||
          fields instanceof HTMLSelectElement
        ) {
          fields.value = value;
        }
        any = any || value.length > 0;
      }

      if (any) setRestored(true);
    } catch {
      // A private window, cleared site data, or storage disabled entirely. The form works
      // without it, so there is nothing to report and nothing to recover.
    }
  }, []);

  const saveDraft = React.useCallback(() => {
    const form = formRef.current;
    if (!form) return;

    try {
      const data = new FormData(form);
      const draft: Draft = {};

      for (const [name, value] of data.entries()) {
        if (typeof value !== "string") continue;
        // Never persist the honeypot or the timing stamp: one would give a returning visitor
        // a filled trap, the other would make a resumed form look instant to the server.
        if (name === "hp" || name === "elapsedMs") continue;

        if (arrays.has(name)) {
          draft[name] = [...((draft[name] as string[]) ?? []), value];
        } else {
          draft[name] = value;
        }
      }

      window.localStorage.setItem(storageKey, JSON.stringify(draft));
    } catch {
      // Storage full or unavailable. Losing the draft is a better outcome than the form
      // failing, so it is not worth surfacing.
    }
  }, [arrays, storageKey]);

  const clearDraft = React.useCallback(() => {
    try {
      window.localStorage.removeItem(storageKey);
    } catch {
      // Nothing to do about it.
    }
  }, [storageKey]);

  React.useEffect(() => {
    if (state.status === "success") clearDraft();
  }, [state.status, clearDraft]);

  // --------------------------------------------------------------------- navigation

  const goTo = React.useCallback(
    (index: number) => {
      shouldFocus.current = true;
      setStep(Math.max(0, Math.min(index, steps.length - 1)));
    },
    [steps.length],
  );

  // A server error can belong to an earlier step. Send the person to the first one that has a
  // problem, or they are told something is wrong on a screen that looks fine.
  React.useEffect(() => {
    if (state.status !== "error" || !state.fieldErrors) return;
    const indexes = Object.keys(state.fieldErrors).map((field) => fieldStep[field] ?? 0);
    if (indexes.length === 0) return;
    invalid.current = state.fieldErrors;
    goTo(Math.min(...indexes));
  }, [state, fieldStep, goTo]);

  /*
   * One effect for both kinds of focus move, because they compete for the same commit and
   * only one of them can win. A step the person completed sends focus to the new heading. A
   * step that failed sends it to the control that failed, which outranks the heading: being
   * told where you are is worth less than being told what is wrong.
   *
   * No dependency array on purpose. Both triggers are refs, so there is nothing for React to
   * compare, and the body costs two null checks on the renders where neither is set.
   */
  React.useEffect(() => {
    const errors = invalid.current;
    if (errors) {
      invalid.current = null;
      shouldFocus.current = false;
      if (focusFirstInvalid(formRef.current, errors)) return;
    }

    if (!shouldFocus.current) return;
    shouldFocus.current = false;
    headingRef.current?.focus();
  });

  const next = React.useCallback(
    (validate: (index: number, data: FormData) => Record<string, string>) => {
      const form = formRef.current;
      if (!form) return;

      const errors = validate(step, new FormData(form));
      setClientErrors(errors);

      if (Object.keys(errors).length === 0) {
        goTo(step + 1);
        return;
      }

      invalid.current = errors;
    },
    [step, goTo],
  );

  const startAgain = React.useCallback(() => {
    formRef.current?.reset();
    clearDraft();
    setRestored(false);
    setClientErrors({});
    goTo(0);
  }, [clearDraft, goTo]);

  const errorFor = React.useCallback(
    (name: string) => clientErrors[name] ?? state.fieldErrors?.[name],
    [clientErrors, state],
  );

  const formProps = {
    ref: formRef,
    onChange: saveDraft,
    onSubmit: () => {
      // Fires before the action, so the value the server reads is the real elapsed time
      // rather than zero. Computing this during render made every genuine enquiry on the
      // marketplace look like a bot, and the form reported success while writing nothing.
      if (elapsedField.current) {
        elapsedField.current.value = String(Date.now() - renderedAt.current);
      }
    },
  };

  return {
    step,
    steps,
    goTo,
    next,
    back: () => goTo(step - 1),
    restored,
    startAgain,
    errorFor,
    formRef,
    headingRef,
    elapsedField,
    formProps,
  };
}

/** The "we brought your answers back" banner, shown when a draft was restored. */
export function RestoredNotice({ onStartAgain }: { onStartAgain: () => void }) {
  return (
    <div className="mb-6 flex flex-wrap items-center justify-between gap-3 border-y border-line py-4">
      <p className="text-sm text-ink-secondary">We brought back what you had already filled in.</p>
      <button
        type="button"
        onClick={onStartAgain}
        className="rn-label inline-flex min-h-11 items-center gap-2 px-3 hover:bg-ink hover:text-ink-inverse"
      >
        <RotateCcw aria-hidden="true" className="size-4" />
        Start again
      </button>
    </div>
  );
}
